package com.officialrino.com.ui

import android.util.Base64

object AppAssets {
    const val SECRET_KEY = "GHOST_X_SECRET"
    const val LOGIN_HTML = ""
    const val DASHBOARD_HTML = ""

    fun decrypt(encrypted: String, key: String = SECRET_KEY): String {
        val data = Base64.decode(encrypted, Base64.DEFAULT)
        val keyBytes = key.toByteArray(Charsets.UTF_8)
        val result = ByteArray(data.size)
        for (i in data.indices) {
            result[i] = (data[i].toInt() xor keyBytes[i % keyBytes.size].toInt()).toByte()
        }
        return String(result, Charsets.UTF_8)
    }
}
